Pseudo-code:
```typescript
import { ShapeStream } from '@electric-sql/client'

const ELECTRIC_URL = process.env.NEXT_PUBLIC_ELECTRIC_URL

export function createNotesShape(userId: string) {
  return new ShapeStream({
    url: `${ELECTRIC_URL}/v1/shape`,
    params: {
      table: 'notes',
      where: `user_id = '${userId}'`,
    },
    subscribe: true,
  })
}

class ShapeManager {
  private shapes: Map<string, ShapeStream> = new Map()

  async subscribeToNotes(userId: string, onUpdate: (data: any) => void) {
    const shape = createNotesShape(userId)
    shape.subscribe((messages) => {
      for (const message of messages) {
        if (message.headers.action === 'insert' || message.headers.action === 'update') {
          onUpdate(message.value)
        }
      }
    })
    this.shapes.set('notes', shape)
  }

  cleanup() {
    for (const shape of this.shapes.values()) {
      shape.unsubscribe()
    }
  }
}
```

