Pseudo-code:
```typescript
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { supabase } from '../supabase-client'

export const notesKeys = {
  all: ['notes'] as const,
  lists: () => [...notesKeys.all, 'list'] as const,
  list: (filters: string) => [...notesKeys.lists(), { filters }] as const,
  details: () => [...notesKeys.all, 'detail'] as const,
  detail: (id: string) => [...notesKeys.details(), id] as const,
}

export function useNotes() {
  return useQuery({
    queryKey: notesKeys.lists(),
    queryFn: async () => {
      const { data, error } = await supabase
        .from('notes')
        .select('id, path, title, updated_at')
        .order('updated_at', { ascending: false })
      if (error) throw error
      return data
    }
  })
}

export function useNote(id: string) {
  return useQuery({
    queryKey: notesKeys.detail(id),
    queryFn: async () => {
      const { data, error } = await supabase
        .from('notes')
        .select('*')
        .eq('id', id)
        .single()
      if (error) throw error
      return data
    },
    enabled: !!id,
  })
}

export function useCreateNote() {
  const queryClient = useQueryClient()

  return useMutation({
    mutationFn: async (note: { title: string; content: string; path: string }) => {
      const { data, error } = await supabase
        .from('notes')
        .insert(note)
        .select()
        .single()
      if (error) throw error
      return data
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: notesKeys.lists() })
    }
  })
}
```

