1. Create lib/supabase-realtime.ts module
2. Implement subscribeToNotes(onUpdate) function:
   - Subscribe to postgres_changes on notes table
   - Listen for INSERT, UPDATE, DELETE events
   - Filter by user_id on client side
3. Integrate with React Query:
   - On INSERT: Add to cache via queryClient.setQueryData
   - On UPDATE: Update cache for specific note
   - On DELETE: Remove from cache
4. Create useRealtimeNotes() hook:
   - Combines useNotes() with Realtime subscription
   - Auto-subscribes on mount, unsubscribes on unmount
5. Add connection status indicator:
   - Show green dot when connected
   - Show yellow dot when reconnecting
   - Show red dot when disconnected
6. Handle edge cases:
   - Dedup: Ignore events for own mutations
   - Stale data: Refetch if missed events during disconnect

Pseudo-code:
```typescript
import { supabase } from './supabase-client'
import { useQueryClient } from '@tanstack/react-query'
import { notesKeys } from './hooks/useNotes'

export function subscribeToNotes(userId: string, onUpdate: (payload: any) => void) {
  const channel = supabase
    .channel('notes-changes')
    .on(
      'postgres_changes',
      { 
        event: '*', 
        schema: 'public', 
        table: 'notes',
        filter: `user_id=eq.${userId}`
      },
      (payload) => {
        console.log('Realtime event:', payload)
        onUpdate(payload)
      }
    )
    .subscribe()

  return () => {
    channel.unsubscribe()
  }
}

export function useRealtimeNotes() {
  const queryClient = useQueryClient()
  const { data: user } = useUser()

  useEffect(() => {
    if (!user) return

    const unsubscribe = subscribeToNotes(user.id, (payload) => {
      const { eventType, new: newRecord, old: oldRecord } = payload

      if (eventType === 'INSERT') {
        queryClient.setQueryData(notesKeys.lists(), (old: any[]) => 
          [newRecord, ...old]
        )
      } else if (eventType === 'UPDATE') {
        queryClient.setQueryData(notesKeys.detail(newRecord.id), newRecord)
        queryClient.invalidateQueries({ queryKey: notesKeys.lists() })
      } else if (eventType === 'DELETE') {
        queryClient.setQueryData(notesKeys.lists(), (old: any[]) => 
          old.filter(note => note.id !== oldRecord.id)
        )
      }
    })

    return unsubscribe
  }, [user, queryClient])

  return useNotes()
}
```

