'use client'
import { useState } from 'react'
import { useRealtimeNotes } from '@/lib/hooks/useNotes'
import { NoteEditor } from '@/components/NoteEditor'
import { GraphView } from '@/components/GraphView'

export default function NotesPage() {
  const [selectedNoteId, setSelectedNoteId] = useState<string | null>(null)
  const [searchQuery, setSearchQuery] = useState('')
  const { data: notes, isLoading } = useRealtimeNotes()
  const { data: currentNote } = useNote(selectedNoteId)
  const updateNote = useUpdateNote()

  const filteredNotes = notes?.filter(note => 
    note.title.toLowerCase().includes(searchQuery.toLowerCase())
  )

  return (
    <div className="flex h-screen">
      {/* Sidebar */}
      <aside className="w-1/5 border-r">
        <input 
          type="search" 
          placeholder="Search notes..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
          className="w-full p-2 border-b"
        />
        <ul className="overflow-y-auto">
          {filteredNotes?.map(note => (
            <li 
              key={note.id}
              onClick={() => setSelectedNoteId(note.id)}
              className={selectedNoteId === note.id ? 'bg-blue-100' : ''}
            >
              <div className="p-2">
                <h3>{note.title}</h3>
                <span className="text-sm text-gray-500">
                  {new Date(note.updated_at).toLocaleDateString()}
                </span>
              </div>
            </li>
          ))}
        </ul>
      </aside>

      {/* Editor */}
      <main className="flex-1">
        {currentNote ? (
          <NoteEditor
            key={currentNote.id}
            initialContent={currentNote.content}
            onSave={(markdown) => updateNote.mutate({ id: currentNote.id, content: markdown })}
          />
        ) : (
          <div className="flex items-center justify-center h-full text-gray-400">
            Select a note or create a new one
          </div>
        )}
      </main>

      {/* Graph Panel */}
      <aside className="w-1/4 border-l">
        {selectedNoteId && <GraphView noteId={selectedNoteId} />}
      </aside>
    </div>
  )
}
```
